import { createSlice } from "@reduxjs/toolkit";
const initialState = {
  byKey: {},
  pendingNavigation: {}
};
const surfacesSlice = createSlice({
  name: "surfaces",
  initialState,
  reducers: {
    registerSurface(state, action) {
      const reg = action.payload;
      state.byKey[reg.surfaceKey] = reg;
    },
    unregisterSurface(state, action) {
      delete state.byKey[action.payload];
      delete state.pendingNavigation[action.payload];
    },
    setPendingNavigation(state, action) {
      const { surfaceKey, conversationId, reason } = action.payload;
      state.pendingNavigation[surfaceKey] = { conversationId, reason };
    },
    clearPendingNavigation(state, action) {
      delete state.pendingNavigation[action.payload.surfaceKey];
    }
  }
});
const {
  registerSurface,
  unregisterSurface,
  setPendingNavigation,
  clearPendingNavigation
} = surfacesSlice.actions;
const surfacesReducer = surfacesSlice.reducer;
var surfaces_slice_default = surfacesSlice.reducer;
const selectSurfaceRegistration = (surfaceKey) => (state) => state.surfaces?.byKey?.[surfaceKey];
const selectPendingNavigation = (surfaceKey) => (state) => state.surfaces?.pendingNavigation?.[surfaceKey];
export {
  clearPendingNavigation,
  surfaces_slice_default as default,
  registerSurface,
  selectPendingNavigation,
  selectSurfaceRegistration,
  setPendingNavigation,
  surfacesReducer,
  unregisterSurface
};
